const nav = [ { id: 'accueil', label: 'Vue d’ensemble', icon: LayoutDashboard }, { id: 'biens', label: 'Mes biens', icon: Building2 }, { id: 'locataires', label: 'Locataires', icon: Users }, { id: 'locations', label: 'Locations & baux', icon: FileText }, { id: 'loyers', label: 'Loyers & paiements', icon: Wallet }, { id: 'sejours', label: 'Courte durée', icon: CalendarDays } ];
