  const [workspaceDialog,setWorkspaceDialog]=useState(false); const [spaces,setSpaces]=useState<Space[]>([]); const spaceIdRef=useRef(''); const [spaceId,setSpaceId]=useState(''); const demoSpaces=useRef<Record<string,State>>({default:demoState()}); const demoActive=useRef('default');
