  const [toast, setToast] = useState(''); const toastTimer = useRef<ReturnType<typeof setTimeout> | null>(null); const [installHelp, setInstallHelp] = useState(false); const [installEvent, setInstallEvent] = useState<InstallPromptEvent | null>(null); const installing = useRef(false); const [offline, setOffline] = useState(false);
  const state = demo ? sample : real; const stateRef = useRef(state); stateRef.current = state; const notifications = alerts(state); const unread = notifications.filter(n => !state.seen.includes(n.id)).length;
  const activity=activityOf(state.profile),isRealEstate=activity==='realestate';
  const visibleNav=isRealEstate?nav.map(n=>n.id==='locations'&&state.profile.mode==='owner'?{...n,label:'Mes locations & baux'}:n):inventoryNav.map(n=>n.id==='inventaire'?{...n,label:activity==='animals'?'Mes animaux':activity==='equipment'?'Matériel & bagages':'Mes biens',icon:activity==='animals'?PawPrint:Package}:n);
