  function add(entity: Entity, defaults: Record<string, unknown> = {}) {
    if(entity==='tenants'||entity==='leases'){setTenantSetup(defaults as {propertyId?:string;tenantId?:string});return;}
    if (['leases', 'expenses', 'tickets', 'reservations'].includes(entity) && !state.properties.length) { go('biens'); notice('Ajoutez d’abord le logement concerné.'); setForm({ entity: 'properties', initial: defaultRecord('properties', state) }); return; }
    if (entity === 'payments' && !state.leases.length) { go('locations'); notice('Créez d’abord la location pour enregistrer un loyer.'); return; }
    const initial={...defaultRecord(entity,state),...defaults};setForm({entity,initial});
  }
  const actions: Actions = {isDemo:demo,demo:()=>{closeContext();setSearch('');setDemo(true);go('accueil');},canPro:subscription.isPro||demo,pro:feature=>setProDialog({feature}),contract:(leaseId='')=>{if(!demo&&!subscription.isPro){setProDialog({feature:'contracts'});return;}setDocumentTab('contracts');setContractDraft({leaseId});}, selectMonth:setPeriod, tenant:setTenantDetail,add, edit: (entity, item) => setForm({ entity, initial: { ...(item as Record<string, unknown>) } }), remove: (entity, id) => setDeleting({ entity, id }), go, pay: (leaseId, month) => { const l = state.leases.find(l => l.id === leaseId); if (l) add('payments', { leaseId, period: month, amount: balanceFor(state, l, month) }); }, inspect: setInspected, mutate, notice, remind: (leaseId, month) => setReminder({ leaseId, period: month }), importProperties: () => {if(!demo&&!subscription.isPro)setProDialog({feature:'import'});else setImporting(true);} };
