  function findSearchResults(query:string){const term=query.trim().toLocaleLowerCase('fr');return term ? isRealEstate ? [...state.properties.filter(p => (p.name + ' ' + p.city + ' ' + p.address).toLowerCase().includes(term)).map(p => ({ id: p.id, name: p.name, detail: p.city + ' · Bien', onClick: () => { setInspected(p); setSearchOpen(false); } })), ...state.tenants.filter(t => (t.name + t.phone + t.email).toLowerCase().includes(term)).map(t => ({ id: t.id, name: t.name, detail: 'Locataire', onClick: () => { go('locataires');setTenantDetail(t.id); setSearchOpen(false); } }))].slice(0, 6) : (state.assets||[]).filter(a=>(a.name+' '+a.reference+' '+a.location).toLowerCase().includes(term)).slice(0,6).map(a=>({id:a.id,name:a.name,detail:a.location||a.category,onClick:()=>{go('inventaire');setSearch(a.name);setSearchOpen(false);}})) : []}
